def build_prefix(numbers):
    prefix = [0]
    for value in numbers:
        prefix.append(prefix[-1] + value)
    return prefix

def range_sum(prefix, left, right):
    return prefix[right] - prefix[left]

class FenwickTree:
    def __init__(self, size):
        self.tree = [0] * (size + 1)

    def add(self, index, delta):
        index += 1
        while index < len(self.tree):
            self.tree[index] += delta
            index += index & -index

    def prefix_sum(self, end):
        total = 0
        while end > 0:
            total += self.tree[end]
            end -= end & -end
        return total

    def range_sum(self, left, right):
        return self.prefix_sum(right) - self.prefix_sum(left)

class SegmentTree:
    def __init__(self, numbers):
        self.n = len(numbers)
        self.tree = [0] * (2 * self.n)
        self.tree[self.n:] = numbers
        for index in range(self.n - 1, 0, -1):
            self.tree[index] = self.tree[2 * index] + self.tree[2 * index + 1]

    def set(self, index, value):
        index += self.n
        self.tree[index] = value
        while index > 1:
            index //= 2
            self.tree[index] = self.tree[2 * index] + self.tree[2 * index + 1]

    def range_sum(self, left, right):
        left += self.n; right += self.n; total = 0
        while left < right:
            if left % 2: total += self.tree[left]; left += 1
            if right % 2: right -= 1; total += self.tree[right]
            left //= 2; right //= 2
        return total

class Node:
    def __init__(self, key=None, value=None):
        self.key, self.value = key, value
        self.prev = self.next = None

class LRUCache:
    def __init__(self, capacity):
        self.capacity, self.nodes = capacity, {}
        self.head, self.tail = Node(), Node()
        self.head.next = self.tail; self.tail.prev = self.head
    def _remove(self, node):
        node.prev.next = node.next; node.next.prev = node.prev
    def _front(self, node):
        node.next = self.head.next; node.prev = self.head
        self.head.next.prev = node; self.head.next = node
    def get(self, key):
        node = self.nodes.get(key)
        if node is None: return None
        self._remove(node); self._front(node); return node.value
    def put(self, key, value):
        if self.capacity <= 0: return
        if key in self.nodes:
            node = self.nodes[key]; node.value = value; self._remove(node)
        else:
            node = self.nodes[key] = Node(key, value)
        self._front(node)
        if len(self.nodes) > self.capacity:
            old = self.tail.prev; self._remove(old); del self.nodes[old.key]

