class BloomFilter:
    def __init__(self, bit_count, hash_count):
        self.bits = [False] * bit_count
        self.hash_count = hash_count
    def _positions(self, value):
        raw = str(value).encode()
        for seed in range(self.hash_count):
            digest = hashlib.sha256(seed.to_bytes(4, "big") + raw).digest()
            yield int.from_bytes(digest[:8], "big") % len(self.bits)
    def add(self, value):
        for position in self._positions(value): self.bits[position] = True
    def __contains__(self, value):
        return all(self.bits[position] for position in self._positions(value))

