class CountMinSketch:
    def __init__(self, width, depth):
        self.width = width
        self.table = [[0] * width for _ in range(depth)]
    def _index(self, value, row):
        raw = f"{row}:{value}".encode()
        return int.from_bytes(hashlib.sha256(raw).digest()[:8], "big") % self.width
    def update(self, value, count=1):
        for row in range(len(self.table)):
            self.table[row][self._index(value, row)] += count
    def estimate(self, value):
        return min(self.table[row][self._index(value, row)] for row in range(len(self.table)))

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]
    def union(self, a, b):
        root_a, root_b = self.find(a), self.find(b)
        if root_a == root_b: return False
        if self.size[root_a] < self.size[root_b]: root_a, root_b = root_b, root_a
        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]
        return True

def build_sparse_min(numbers):
    table = [numbers[:]]
    length = 2
    while length <= len(numbers):
        half = length // 2
        previous = table[-1]
        table.append([min(previous[i], previous[i + half])
                      for i in range(len(numbers) - length + 1)])
        length *= 2
    return table

def sparse_range_min(table, left, right):
    length = right - left
    level = length.bit_length() - 1
    width = 1 << level
    return min(table[level][left], table[level][right - width])

def next_greater(numbers):
    answer = [-1] * len(numbers)
    stack = []
    for index, value in enumerate(numbers):
        while stack and numbers[stack[-1]] < value:
            answer[stack.pop()] = value
        stack.append(index)
    return answer

from collections import deque

def sliding_window_max(numbers, k):
    if k <= 0 or k > len(numbers): return []
    queue, result = deque(), []
    for index, value in enumerate(numbers):
        while queue and queue[0] <= index - k: queue.popleft()
        while queue and numbers[queue[-1]] <= value: queue.pop()
        queue.append(index)
        if index >= k - 1: result.append(numbers[queue[0]])
    return result
